-- Spec 007 test data: synthetic parcel polygons across Utah, generated by the
-- native DuckDB CLI (not the WASM engine under test). A template: run it
-- through `npm run large-data` (scripts/large-data.mjs), which fills in
-- {{rows}}, {{out}} and {{select}}.
--
-- 12-vertex rings; 80% clustered into 20 "cities", the rest scattered; six
-- attributes; Hilbert-sorted so row groups are spatially compact (what good
-- GeoParquet writers do); a GeoParquet 1.1-style `bbox` covering struct
-- unless {{select}} drops it.
INSTALL spatial; LOAD spatial;
CREATE OR REPLACE TABLE p AS
WITH ids AS (SELECT range AS i FROM range({{rows}})),
c AS (
  SELECT i,
    hash(i) % 1000 / 1000.0 AS u, hash(i * 7 + 1) % 1000003 / 1000003.0 AS a, hash(i * 13 + 5) % 1000003 / 1000003.0 AS b,
    hash(i * 31 + 9) % 20 AS city
  FROM ids
),
xy AS (
  SELECT i, city,
    CASE WHEN u < 0.8
      THEN -112.6 + (city % 5) * 0.75 + (a - 0.5) * 0.35
      ELSE -114.0 + a * 5.0 END AS x,
    CASE WHEN u < 0.8
      THEN 37.4 + (city // 5) * 1.2 + (b - 0.5) * 0.3
      ELSE 37.0 + b * 5.0 END AS y
  FROM c
)
SELECT
  i AS parcel_id,
  printf('P%08d', i) AS parcel_code,
  ['R1','R2','C1','I1','AG'][1 + (hash(i * 3) % 5)::BIGINT] AS zone,
  round((hash(i * 5) % 50000) / 1000.0, 3) AS acres,
  (hash(i * 11) % 2000000)::INTEGER AS value,
  (1900 + hash(i * 17) % 124)::SMALLINT AS year_built,
  ST_MakePolygon(ST_MakeLine(list_transform(range(13), lambda k:
    ST_Point(x + cos(2 * pi() * (k % 12) / 12) * 0.0004 * (1 + (hash(i + k % 12) % 5)::DOUBLE / 10.0),
             y + sin(2 * pi() * (k % 12) / 12) * 0.0003 * (1 + (hash(i + k % 12) % 5)::DOUBLE / 10.0))))) AS geom
FROM xy;
CREATE OR REPLACE TABLE p AS
  SELECT *, {'xmin': ST_XMin(geom), 'ymin': ST_YMin(geom), 'xmax': ST_XMax(geom), 'ymax': ST_YMax(geom)} AS bbox
  FROM p ORDER BY ST_Hilbert(geom, ST_Extent(ST_MakeEnvelope(-114.1, 36.9, -108.9, 42.1)));
COPY (SELECT {{select}} FROM p) TO '{{out}}' (FORMAT PARQUET, ROW_GROUP_SIZE 100000, COMPRESSION ZSTD);
